python3 -c "
import json, base64, zlib, struct
from collections import Counter

def decode_png(b64):
    data = base64.b64decode(b64)
    pos = 8; w = h = 0; idat = bytearray()
    while pos < len(data):
        length, ctype = struct.unpack('>I4s', data[pos:pos+8])
        chunk = data[pos+8:pos+8+length]; pos += 12 + length
        if ctype == b'IHDR': w, h, bd, ct, _, _, _ = struct.unpack('>IIBBBBB', chunk)
        elif ctype == b'IDAT': idat.extend(chunk)
    raw = zlib.decompress(bytes(idat))
    bpp = 3 if ct == 2 else 4; stride = w * bpp
    rows = []; i = 0; prev = bytearray(stride)
    for y in range(h):
        f = raw[i]; i += 1; row = bytearray(raw[i:i+stride]); i += stride
        if f == 1:
            for x in range(bpp, stride): row[x] = (row[x] + row[x-bpp]) & 255
        elif f == 2:
            for x in range(stride): row[x] = (row[x] + prev[x]) & 255
        elif f == 3:
            for x in range(stride):
                a = row[x-bpp] if x >= bpp else 0
                row[x] = (row[x] + ((a + prev[x]) >> 1)) & 255
        elif f == 4:
            for x in range(stride):
                a = row[x-bpp] if x >= bpp else 0; b = prev[x]; c = prev[x-bpp] if x >= bpp else 0
                p = a + b - c; pa, pb, pc = abs(p-a), abs(p-b), abs(p-c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                row[x] = (row[x] + pr) & 255
        rows.append(row); prev = row
    return w, h, bpp, rows

for line in open('/logs/agent/opencode.txt'):
    d = json.loads(line)
    if d.get('type') == 'tool_use' and d['part']['tool'] == 'loophole_render':
        p = d['part']
        view = p['state']['input']['view']
        url = p['state']['attachments'][0]['url'].split(',', 1)[1]
        w, h, bpp, rows = decode_png(url)
        if view == 'front':
            # print sample RGBs across y at x=240 and x=100
            for y in [0, 100, 150, 195, 235, 250, 300, 350]:
                print(y, [tuple(rows[y][x*bpp:x*bpp+3]) for x in [50, 150, 240, 350, 430]])
"

